(1283100, 165114, 35207, '<td valign="top">Nice use of the selective coloring (im sure it has a more professional name, but i cant think of it)  i think it might look kinda neat if the water was still in color.....9</td>', 'Nice use of the selective coloring (im sure it has a more professional name, but i cant think of it)  i think it might look kinda neat if the water was still in color.....9', '2005-04-11 01:06:16.000000', NULL, 1),
(1283119, 164856, 35895, '<td valign="top">nice shot!</td>', 'nice shot!', '2005-04-11 01:11:06.000000', NULL, 1),
(1283121, 163858, 30822, '<td valign="top">lol! Had to give a 5 because the foreground is out of focus. I know the action shots are tough but you have to plan ahead:)</td>', 'lol! Had to give a 5 because the foreground is out of focus. I know the action shots are tough but you have to plan ahead:)', '2005-04-11 01:11:58.000000', NULL, 1),
(1283128, 164797, 10170, '<td valign="top">Absolutely exceptional.  Lighting is supberb and the timing perfect, as it would have to be.  If you don''t have an explanation of what equipment you used for the timing here on the photo description could you do me a favour and send me the details, with a web link if appropriate, as I am after some way of doing similar shots myself.  10+</td>', 'Absolutely exceptional.  Lighting is supberb and the timing perfect, as it would have to be.  If you don''t have an explanation of what equipment you used for the timing here on the photo description could you do me a favour and send me the details, with a web link if appropriate, as I am after some way of doing similar shots myself.  10+', '2005-04-11 01:13:48.000000', NULL, 1),
(1283149, 164720, 327, '<td valign="top">This is a nice example of action-- just a busy background. Still your colors are very good. Maybe a tighter crop here would of focused the viewer to the action. ? I find myself looking at the baby, the couple and the parked cars. Just my 2 cents. All the best.</td>', 'This is a nice example of action-- just a busy background. Still your colors are very good. Maybe a tighter crop here would of focused the viewer to the action. ? I find myself looking at the baby, the couple and the parked cars. Just my 2 cents. All the best.', '2005-04-11 01:18:22.000000', NULL, 1),
(1283153, 163896, 327, '<td valign="top">Good example only wish he was facing the camera. Good luck.</td>', 'Good example only wish he was facing the camera. Good luck.', '2005-04-11 01:19:07.000000', NULL, 1),
(1283155, 164217, 327, '<td valign="top">Nice colors and light. Looks like fun and plenty of action.</td>', 'Nice colors and light. Looks like fun and plenty of action.', '2005-04-11 01:19:31.000000', NULL, 1),
