(1283650, 165057, 8643, '<td valign="top">This seems rather blurry to me - sorry if it was intentional!</td>', 'This seems rather blurry to me - sorry if it was intentional!', '2005-04-11 05:50:06.000000', NULL, 1),
(1283651, 165032, 2798, '<td valign="top">This is really something. I''d love to know how you took this. It looks like a fast shutter in low light so the ISO must be right up but the picture looks smooth. Perhaps Neat Image earned its keep here? Anyway very very well done getting the shot. Good light and composition with a nice tone to the image. 10</td>', 'This is really something. I''d love to know how you took this. It looks like a fast shutter in low light so the ISO must be right up but the picture looks smooth. Perhaps Neat Image earned its keep here? Anyway very very well done getting the shot. Good light and composition with a nice tone to the image. 10', '2005-04-11 05:54:41.000000', NULL, 1),
(1283652, 164601, 2798, '<td valign="top">Great subject and composition but seems to be lacking contrast. A little more work would bring out the detail on your subject and enhance the drama. Overall an excellent shot. 8</td>', 'Great subject and composition but seems to be lacking contrast. A little more work would bring out the detail on your subject and enhance the drama. Overall an excellent shot. 8', '2005-04-11 05:59:22.000000', NULL, 1),
(1283655, 164630, 2798, '<td valign="top">Great motion and atmosphere in this shot. Would love to know how the blurred portions at the sides were done. Colours are a little posterised but that''s a big part of the atmosphere.  A real winner of a shot. 10</td>', 'Great motion and atmosphere in this shot. Would love to know how the blurred portions at the sides were done. Colours are a little posterised but that''s a big part of the atmosphere.  A real winner of a shot. 10', '2005-04-11 06:02:16.000000', NULL, 1),
(1283656, 164452, 2798, '<td valign="top">Sacrilege! A very clean, static shot. I think I''d have liked to see some motion in the hammer. Otherwise a good effort. 8</td>', 'Sacrilege! A very clean, static shot. I think I''d have liked to see some motion in the hammer. Otherwise a good effort. 8', '2005-04-11 06:04:25.000000', NULL, 1),
(1283659, 163858, 31955, '<td valign="top">Sorry but this doesn''t look extreme at all.  An old idea poorly executed.Sorry  3</td>', 'Sorry but this doesn''t look extreme at all.  An old idea poorly executed.Sorry  3', '2005-04-11 06:09:36.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1283667, 164994, 2798, '<td valign="top">Great shot. My only comment is that there seems to be a green colour cast to everything. White balance off? Would have been nice to see the flipper''s face too but I understand that might not be very easy. :) 8</td>', 'Great shot. My only comment is that there seems to be a green colour cast to everything. White balance off? Would have been nice to see the flipper''s face too but I understand that might not be very easy. :) 8', '2005-04-11 06:19:54.000000', NULL, 1),
(1283668, 164713, 2798, '<td valign="top">A good attempt at a magazine style "car in motion" shot. Lacks detail in the black car and overall lacks contrast. The brightness of the sky has forced all the other values into the dark end of the range. 7</td>', 'A good attempt at a magazine style "car in motion" shot. Lacks detail in the black car and overall lacks contrast. The brightness of the sky has forced all the other values into the dark end of the range. 7', '2005-04-11 06:22:15.000000', NULL, 1),
(1283669, 164959, 18552, '<td valign="top">This is a really nice photo for this challenge. It would have been nice to see the whole sail - perhaps a portrait orientation would have worked well for this shot.<br/><br/><i>Message edited by author 2005-04-18 02:19:41.</i></td>', 'This is a really nice photo for this challenge. It would have been nice to see the whole sail - perhaps a portrait orientation would have worked well for this shot.', '2005-04-11 06:22:56.000000', '2005-04-18 03:19:41.000000', 1),
(1283672, 164234, 2798, '<td valign="top">Not a bad idea but what is that background all about? It''s very distracting and is in better focus than the spinning globe. Perhaps a slow sync flash here could have stopped the motion of the globe while keeping the motion blur. That focus would have helped draw the eye back to the globe that should be the main subject of the image. Also, if the pattern on the backdrop is meant to be symbolic then perhaps use some negative space around the globe to really make that aparrent. Finally there is a brown/yellow tint to the image that is most aparrent in the whiter areas of the backdrop. This shot is a really good idea that needs just a little work in my view. 7</td>', 'Not a bad idea but what is that background all about? It''s very distracting and is in better focus than the spinning globe. Perhaps a slow sync flash here could have stopped the motion of the globe while keeping the motion blur. That focus would have helped draw the eye back to the globe that should be the main subject of the image. Also, if the pattern on the backdrop is meant to be symbolic then perhaps use some negative space around the globe to really make that aparrent. Finally there is a brown/yellow tint to the image that is most aparrent in the whiter areas of the backdrop. This shot is a really good idea that needs just a little work in my view. 7', '2005-04-11 06:26:24.000000', NULL, 1),
(1283674, 164234, 18552, '<td valign="top">The spinning globe is really nice. The background is really bad though - this would have been so nice against a plain black or white background.</td>', 'The spinning globe is really nice. The background is really bad though - this would have been so nice against a plain black or white background.', '2005-04-11 06:26:44.000000', NULL, 1),
(1283676, 164856, 18552, '<td valign="top">Wow, Tiger Woods in person! Nice shot, too. I like the way his head is still and the rest of him is moving.</td>', 'Wow, Tiger Woods in person! Nice shot, too. I like the way his head is still and the rest of him is moving.', '2005-04-11 06:28:17.000000', NULL, 1),
(1283677, 164642, 2798, '<td valign="top">Good shot but cropped just a little too far right for my taste. I would have liked the horses just a little more towards the centre. Also a bump in colour and contrast would have added drama. 7</td>', 'Good shot but cropped just a little too far right for my taste. I would have liked the horses just a little more towards the centre. Also a bump in colour and contrast would have added drama. 7', '2005-04-11 06:28:58.000000', NULL, 1),
(1283679, 163991, 2798, '<td valign="top">Great capture. The slow sync flash really worked for you here. My only comment is that the red shirts in the background are a little distracting. Perhaps B&amp;W would help? 10</td>', 'Great capture. The slow sync flash really worked for you here. My only comment is that the red shirts in the background are a little distracting. Perhaps B&W would help? 10', '2005-04-11 06:30:32.000000', NULL, 1),
(1283680, 163588, 18552, '<td valign="top">This is a great shot - the bike against the lovely sky is very nice. It would have been very nice to see the rest of the bike and rider.</td>', 'This is a great shot - the bike against the lovely sky is very nice. It would have been very nice to see the rest of the bike and rider.', '2005-04-11 06:30:36.000000', NULL, 1),
(1283682, 164762, 32602, '<td valign="top">Very funny!</td>', 'Very funny!', '2005-04-11 06:32:38.000000', NULL, 1),
