(1285030, 164835, 19952, '<td valign="top">Absolutely brilliant capture! This is such a great action shot, and it definitely qualifies as extreme. :-)</td>', 'Absolutely brilliant capture! This is such a great action shot, and it definitely qualifies as extreme. :-)', '2005-04-11 23:09:51.000000', NULL, 1),
(1285040, 164856, 19952, '<td valign="top">Lucky! :-) This is a brilliant shot that really draws the focus right onto Tiger''s face. My only critique is that it''s a bit too bright, so it would look better with slightly deeper tones. Other than that, this is a great action capture with outstanding composition.</td>', 'Lucky! :-) This is a brilliant shot that really draws the focus right onto Tiger''s face. My only critique is that it''s a bit too bright, so it would look better with slightly deeper tones. Other than that, this is a great action capture with outstanding composition.', '2005-04-11 23:14:18.000000', NULL, 1),
(1285042, 165120, 31167, '<td valign="top">I like how the rotaion gives that extreme perspective</td>', 'I like how the rotaion gives that extreme perspective', '2005-04-11 23:14:44.000000', NULL, 1),
(1285046, 164285, 19952, '<td valign="top">Great action with excellent background motion blur. I would like the subject itself to be less blurred since that would give the viewer something to focus on, but this is still a nice action photo.</td>', 'Great action with excellent background motion blur. I would like the subject itself to be less blurred since that would give the viewer something to focus on, but this is still a nice action photo.', '2005-04-11 23:16:23.000000', NULL, 1),
(1285054, 165127, 19952, '<td valign="top">Nice action capture. For this shot, I think it would be okay to sacrifice a bit of detail on the subject in order to have darker, richer tones throughout the image. Still, this is a really excellent photo.</td>', 'Nice action capture. For this shot, I think it would be okay to sacrifice a bit of detail on the subject in order to have darker, richer tones throughout the image. Still, this is a really excellent photo.', '2005-04-11 23:20:45.000000', NULL, 1),
(1285074, 164654, 19952, '<td valign="top">Outstanding action capture and nice tight composition. Really excellent photo.</td>', 'Outstanding action capture and nice tight composition. Really excellent photo.', '2005-04-11 23:43:12.000000', NULL, 1),
(1285081, 165186, 19952, '<td valign="top">Nice action capture. I think this shot would look better if you boosted the contrast a bit to keep it from looking so dark or muddy throughout. But you did a great job with composition and with grabbing an excellent action shot.</td>', 'Nice action capture. I think this shot would look better if you boosted the contrast a bit to keep it from looking so dark or muddy throughout. But you did a great job with composition and with grabbing an excellent action shot.', '2005-04-11 23:47:42.000000', NULL, 1),
(1285086, 164935, 19952, '<td valign="top">You have a talent for capturing action that most people wouldn''t have even noticed. :-) Very nicely done.</td>', 'You have a talent for capturing action that most people wouldn''t have even noticed. :-) Very nicely done.', '2005-04-11 23:51:00.000000', NULL, 1),
(1285091, 165103, 19952, '<td valign="top">Funny! Nice job creating an action shot out of this scene.</td>', 'Funny! Nice job creating an action shot out of this scene.', '2005-04-11 23:53:24.000000', NULL, 1),
