(1285185, 164234, 24951, '<td valign="top">How incredibly interesting and such a simple idea as well as being a pretty good photo. The spinning globe is quite clear. Interesting background given the images of transportation. Would have like a bit more variety regarding tint.8</td>', 'How incredibly interesting and such a simple idea as well as being a pretty good photo. The spinning globe is quite clear. Interesting background given the images of transportation. Would have like a bit more variety regarding tint.8', '2005-04-12 00:52:40.000000', NULL, 1),
(1285193, 165085, 33542, '<td valign="top">This shot would have been really great if the background were in focus, i.e. only the players were blurred... as it is, it looks more accidental than planned, imo</td>', 'This shot would have been really great if the background were in focus, i.e. only the players were blurred... as it is, it looks more accidental than planned, imo', '2005-04-12 00:56:35.000000', NULL, 1),
(1285200, 164838, 22537, '<td valign="top">Excellent perspective on this shot but I would ahve liked it more had the gun not been supported.  Strong composition and quality.  Good luck.</td>', 'Excellent perspective on this shot but I would ahve liked it more had the gun not been supported.  Strong composition and quality.  Good luck.', '2005-04-12 01:02:52.000000', NULL, 1),
(1285203, 165072, 22537, '<td valign="top">Cool shot though I dont get the "extreme action" slant on it.  The image quality is superb and yo''veu handled the potential for "blowout" from the sun very well.  Good luck.  6</td>', 'Cool shot though I dont get the "extreme action" slant on it.  The image quality is superb and yo''veu handled the potential for "blowout" from the sun very well.  Good luck.  6', '2005-04-12 01:05:29.000000', NULL, 1),
