(1285242, 163466, 29904, '<td valign="top">Great espression, but too much shadow on his face and nothing is clear enough.</td>', 'Great espression, but too much shadow on his face and nothing is clear enough.', '2005-04-12 02:09:07.000000', NULL, 1),
(1285244, 163858, 29904, '<td valign="top">Really fun!  Nice dof, color and expression.  I would only have less sharp light up on the face.  9  :)</td>', 'Really fun!  Nice dof, color and expression.  I would only have less sharp light up on the face.  9  :)', '2005-04-12 02:12:40.000000', NULL, 1),
