(1285450, 165010, 35895, '<td valign="top">Killer composition. I really like this shot! Good Job! This, in my opinion, is the best photo for this challenge.....</td>', 'Killer composition. I really like this shot! Good Job! This, in my opinion, is the best photo for this challenge.....', '2005-04-12 09:58:25.000000', NULL, 1),
(1285462, 165010, 36273, '<td valign="top">Fantastic job. From composition to frozen action, this one stands way out to me in this competition.</td>', 'Fantastic job. From composition to frozen action, this one stands way out to me in this competition.', '2005-04-12 10:17:32.000000', NULL, 1),
(1285464, 165010, 35472, '<td valign="top">This is the best photo for extreme! beatiful siluette and great contrast. and sky...</td>', 'This is the best photo for extreme! beatiful siluette and great contrast. and sky...', '2005-04-12 10:20:01.000000', NULL, 1),
(1285493, 165064, 35720, '<td valign="top">Excellent capture, great timing. One of the best in this challenge, my favorite shot. Good luck!</td>', 'Excellent capture, great timing. One of the best in this challenge, my favorite shot. Good luck!', '2005-04-12 10:48:22.000000', NULL, 1),
