(1286546, 165064, 29009, '<td valign="top">Great color - focus is awesome.  One small thing - the best surfing pictures generally have the crop leading in the direction of the surfer.  That is, the action is moving from the white part of the wave to the part that hasn''t broken yet, so the crop usually less of the breaking wave than the about-to-break part.  Nevertheless, this is a great shot!</td>', 'Great color - focus is awesome.  One small thing - the best surfing pictures generally have the crop leading in the direction of the surfer.  That is, the action is moving from the white part of the wave to the part that hasn''t broken yet, so the crop usually less of the breaking wave than the about-to-break part.  Nevertheless, this is a great shot!', '2005-04-12 22:45:52.000000', NULL, 1),
(1286550, 165127, 29009, '<td valign="top">Nice timing on this one.  A portion of the sky seems a bit blown out; however, the stop action is fabulous and the composition is great.  Good job!</td>', 'Nice timing on this one.  A portion of the sky seems a bit blown out; however, the stop action is fabulous and the composition is great.  Good job!', '2005-04-12 22:47:05.000000', NULL, 1),
(1286552, 165085, 35382, '<td valign="top">nice shot,  I really like it.</td>', 'nice shot,  I really like it.', '2005-04-12 22:49:22.000000', NULL, 1),
(1286553, 164659, 6668, '<td valign="top">Beautiful! Love the coloring!</td>', 'Beautiful! Love the coloring!', '2005-04-12 22:50:38.000000', NULL, 1),
(1286554, 165111, 29009, '<td valign="top">Great stop action shot with good use of depth of field.  I find myself wishing for more of the rail to be showing - it took me extra time to figure out what was happening and I needed the title for explanation.  Overall, just fantastic.</td>', 'Great stop action shot with good use of depth of field.  I find myself wishing for more of the rail to be showing - it took me extra time to figure out what was happening and I needed the title for explanation.  Overall, just fantastic.', '2005-04-12 22:51:15.000000', NULL, 1),
(1286555, 163858, 29009, '<td valign="top">Oh - this is just too funny.  Creative take on the challenge.  One small nit-picky tink - I''d like to have seen a crisp clean iron.  Otherwise, a great job!</td>', 'Oh - this is just too funny.  Creative take on the challenge.  One small nit-picky tink - I''d like to have seen a crisp clean iron.  Otherwise, a great job!', '2005-04-12 22:52:39.000000', NULL, 1),
(1286558, 165125, 29009, '<td valign="top">Excellent composition and focus.  You''ve got it just right!</td>', 'Excellent composition and focus.  You''ve got it just right!', '2005-04-12 22:53:16.000000', NULL, 1),
(1286565, 164997, 33560, '<td valign="top">The action in the photo doesn''t rate as extreme except maybe in Florida .  The photo appears to be rotated clockwise a degree or so.  But I like it;  it''s clearly a beautiful house and the impressionistic effect created by the snow makes it better.</td>', 'The action in the photo doesn''t rate as extreme except maybe in Florida .  The photo appears to be rotated clockwise a degree or so.  But I like it;  it''s clearly a beautiful house and the impressionistic effect created by the snow makes it better.', '2005-04-12 23:00:05.000000', NULL, 1),
(1286612, 164630, 16829, '<td valign="top">Fabulous</td>', 'Fabulous', '2005-04-12 23:20:24.000000', NULL, 1),
(1286629, 164835, 33560, '<td valign="top">Hmm.. Extreme by several measures.  It''s a great action shot. <br/> <br/>Though I appreciate the strong bokeh, I wish more of the players faces were in sharper focus.  The lighting seems strange: it seems a little flat and it seems to  produce a cyan cast to the skin.  Still, nice effort.</td>', 'Hmm.. Extreme by several measures.  It''s a great action shot.  Though I appreciate the strong bokeh, I wish more of the players faces were in sharper focus.  The lighting seems strange: it seems a little flat and it seems to  produce a cyan cast to the skin.  Still, nice effort.', '2005-04-12 23:28:12.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1286641, 165125, 22537, '<td valign="top">Not sure whether this is a handstand or a trick shot leaning far back against a wall.The layout is fantastic, colors are not too stark, sharpness is "bang-on" and it fits the challenge very well.  Bumping up to a 6.  Good luck!</td>', 'Not sure whether this is a handstand or a trick shot leaning far back against a wall.The layout is fantastic, colors are not too stark, sharpness is "bang-on" and it fits the challenge very well.  Bumping up to a 6.  Good luck!', '2005-04-12 23:34:11.000000', NULL, 1),
(1286645, 165077, 33560, '<td valign="top">Super caption, very  funny. <br/> <br/>Curiously, the gulls appear to be more blurred than the water.</td>', 'Super caption, very  funny.  Curiously, the gulls appear to be more blurred than the water.', '2005-04-12 23:35:29.000000', NULL, 1),
(1286646, 163858, 22537, '<td valign="top">Though it is not a technically superb shot, it is a hilarious parody.  Very creative and a nice twist on the challenge.  Good luck!</td>', 'Though it is not a technically superb shot, it is a hilarious parody.  Very creative and a nice twist on the challenge.  Good luck!', '2005-04-12 23:35:50.000000', NULL, 1),
(1286649, 165096, 33560, '<td valign="top">Quite beautiful.</td>', 'Quite beautiful.', '2005-04-12 23:36:35.000000', NULL, 1),
(1286654, 163896, 22537, '<td valign="top">This is a fantastic capture and the subject is situated perfectly within the image.  The problem I have is the colors are somewhat mundane and fail to keep my interest.  Good luck.</td>', 'This is a fantastic capture and the subject is situated perfectly within the image.  The problem I have is the colors are somewhat mundane and fail to keep my interest.  Good luck.', '2005-04-12 23:37:42.000000', NULL, 1),
(1286661, 164215, 22537, '<td valign="top">Funny idea.  I used to see improv comics perform "restaurant climbing" under the same slant as you have here.  The use of Sepia has nicely teaked the B&amp;W image and the subjects are all characters in themselves.  The bright areas are a bit blown out and do a disservice to the shot.  Good luck!</td>', 'Funny idea.  I used to see improv comics perform "restaurant climbing" under the same slant as you have here.  The use of Sepia has nicely teaked the B&W image and the subjects are all characters in themselves.  The bright areas are a bit blown out and do a disservice to the shot.  Good luck!', '2005-04-12 23:40:50.000000', NULL, 1),
(1286667, 165040, 33560, '<td valign="top">A gorgeous model wiearing a great expression.  Nice composition, colors, bokeh.  Not much extreme about the action, but I really like the photo.</td>', 'A gorgeous model wiearing a great expression.  Nice composition, colors, bokeh.  Not much extreme about the action, but I really like the photo.', '2005-04-12 23:42:52.000000', NULL, 1),
(1286675, 164238, 33560, '<td valign="top">Super shot, crystalline sharpness and perfect lighting.  An unexpected pleasure.</td>', 'Super shot, crystalline sharpness and perfect lighting.  An unexpected pleasure.', '2005-04-12 23:45:58.000000', NULL, 1),
(1286681, 164177, 29904, '<td valign="top">Excellent action and composition!  Love the possitions of the the players and the ball, love the dust clouds and a lovely green background,  It would be perfect if only cropped a little more and esp if sharper clearer image like ''tackle'' and ''ruck''.  Whites and the ball are a little hot.  Otherwise Cool! - 8</td>', 'Excellent action and composition!  Love the possitions of the the players and the ball, love the dust clouds and a lovely green background,  It would be perfect if only cropped a little more and esp if sharper clearer image like ''tackle'' and ''ruck''.  Whites and the ball are a little hot.  Otherwise Cool! - 8', '2005-04-12 23:47:40.000000', NULL, 1),
(1286687, 163641, 33560, '<td valign="top">Great photo.  I''d be interested to know how 200 microseconds was chosen; if by trial and error, then how many bulbs did it take?</td>', 'Great photo.  I''d be interested to know how 200 microseconds was chosen; if by trial and error, then how many bulbs did it take?', '2005-04-12 23:48:43.000000', NULL, 1),
(1286819, 164178, 35895, '<td valign="top">well thought, i really like this shot</td>', 'well thought, i really like this shot', '2005-04-13 00:25:12.000000', NULL, 1),
(1286894, 165048, 23203, '<td valign="top">Good capture.. more zoom/tighter crop would''ve helped.<br/></td>', 'Good capture.. more zoom/tighter crop would''ve helped.', '2005-04-13 00:56:26.000000', NULL, 1),
(1286903, 165052, 23203, '<td valign="top">Good capture, a tighter crop / extra zoom might have helped</td>', 'Good capture, a tighter crop / extra zoom might have helped', '2005-04-13 00:59:18.000000', NULL, 1),
