(1288731, 164654, 2741, '<td valign="top">Great shot. 7.</td>', 'Great shot. 7.', '2005-04-13 13:57:30.000000', NULL, 1),
(1288837, 165155, 13749, '<td valign="top">wonderful capture, although i''m probably a bit biased as i love to play golf - lighting could be better, and i might even prefer a tighter crop to direct the attention straight to the driver/ball and not the guy and his face.</td>', 'wonderful capture, although i''m probably a bit biased as i love to play golf - lighting could be better, and i might even prefer a tighter crop to direct the attention straight to the driver/ball and not the guy and his face.', '2005-04-13 14:24:21.000000', NULL, 1),
(1288857, 164713, 13749, '<td valign="top">cool, although i wish the driver weren''t looking at the camera and think that the blurred license plate looks a bit odd (maybe you could''ve removed it for the shot?)  but i do love the motion blur of the surroundings and the sharpness of the car.</td>', 'cool, although i wish the driver weren''t looking at the camera and think that the blurred license plate looks a bit odd (maybe you could''ve removed it for the shot?)  but i do love the motion blur of the surroundings and the sharpness of the car.', '2005-04-13 14:28:32.000000', NULL, 1),
(1288865, 165125, 13749, '<td valign="top">i would assume that you rotated this, but some things indicate otherwise (ie: the pants hanging down).  either way, nice looking shot.  the shadows are of minor concern to me, although others might differ in opinion.</td>', 'i would assume that you rotated this, but some things indicate otherwise (ie: the pants hanging down).  either way, nice looking shot.  the shadows are of minor concern to me, although others might differ in opinion.', '2005-04-13 14:31:06.000000', NULL, 1),
(1288870, 164654, 13749, '<td valign="top">wonderful shot - the placement, position, etc. all work well here.</td>', 'wonderful shot - the placement, position, etc. all work well here.', '2005-04-13 14:33:02.000000', NULL, 1),
(1288883, 164177, 30625, '<td valign="top">An excellent capture</td>', 'An excellent capture', '2005-04-13 14:35:35.000000', NULL, 1),
