(1288896, 163855, 13749, '<td valign="top">very inclined to think laurie on this one, and definitely one of the better MX shots in the challenge.</td>', 'very inclined to think laurie on this one, and definitely one of the better MX shots in the challenge.', '2005-04-13 14:40:46.000000', NULL, 1),
(1288941, 165155, 29797, '<td valign="top">An extra point for the leftie... Nice capture!</td>', 'An extra point for the leftie... Nice capture!', '2005-04-13 15:01:36.000000', NULL, 1),
(1289016, 165150, 29797, '<td valign="top">That looks like Cayucos with Morro Rock in the background. Nice little town there. Oh yeah, helluva shot! Extra point for having the b@lls to bring a camera up there! Hope this ribbons!</td>', 'That looks like Cayucos with Morro Rock in the background. Nice little town there. Oh yeah, helluva shot! Extra point for having the b@lls to bring a camera up there! Hope this ribbons!', '2005-04-13 15:21:33.000000', NULL, 1),
(1289021, 163466, 29269, '<td valign="top">For some reason, that strong hot lighted area takes away from the kid''s expression for me. I wish it didn''t have those blown highlights.<br/> <br/>ps. why validate? I do this with my kids all the time...</td>', 'For some reason, that strong hot lighted area takes away from the kid''s expression for me. I wish it didn''t have those blown highlights. ps. why validate? I do this with my kids all the time...', '2005-04-13 15:22:24.000000', NULL, 1),
(1289026, 164695, 29269, '<td valign="top">If you could have taken this shot against the wall, would have been better (bookcase is too distracting IMO)</td>', 'If you could have taken this shot against the wall, would have been better (bookcase is too distracting IMO)', '2005-04-13 15:23:55.000000', NULL, 1),
(1289230, 165150, 31213, '<td valign="top">I paraglide as well.  I''m scared to take my camera with me.  Your crazy!  I''m working on my P2 with my dad right now.  I live in Monterey Bay where people paraglide everyday!  Where was this taken?<br/> <br/>Chris</td>', 'I paraglide as well.  I''m scared to take my camera with me.  Your crazy!  I''m working on my P2 with my dad right now.  I live in Monterey Bay where people paraglide everyday!  Where was this taken? Chris', '2005-04-13 16:37:00.000000', NULL, 1),
(1289264, 165103, 27294, '<td valign="top">Great idea, but despite the motion blur your model still looks still... <br/> <br/>very close to be absolutely awesome!</td>', 'Great idea, but despite the motion blur your model still looks still...  very close to be absolutely awesome!', '2005-04-13 16:44:59.000000', NULL, 1),
(1289272, 165201, 27294, '<td valign="top">I am not sure if your subject would be happy with the shot -b ut it certainly captures the moment and mood well!</td>', 'I am not sure if your subject would be happy with the shot -b ut it certainly captures the moment and mood well!', '2005-04-13 16:46:33.000000', NULL, 1),
