(1291146, 164713, 11895, '<td valign="top">there are near vertical lines in the background just off the left fender, the driver appears to be looking away from the road and toward the camera, overall a little on the dark side, can''t see much detail on the front of the car; I can see action in the motioned-blurred bg and the spinning wheels but it doesn''t strike me as extreme</td>', 'there are near vertical lines in the background just off the left fender, the driver appears to be looking away from the road and toward the camera, overall a little on the dark side, can''t see much detail on the front of the car; I can see action in the motioned-blurred bg and the spinning wheels but it doesn''t strike me as extreme', '2005-04-14 08:56:07.000000', NULL, 1),
(1291149, 165017, 27137, '<td valign="top">don''t know what kind of trick that is but it looks like a mess-up</td>', 'don''t know what kind of trick that is but it looks like a mess-up', '2005-04-14 08:58:03.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1291154, 164856, 11895, '<td valign="top">highlights are blown out, especially on his shoulders, hard for me to think of golf as extreme;  am I supposed to score this higher because I recognize the face?  Does that make it a better photograph?</td>', 'highlights are blown out, especially on his shoulders, hard for me to think of golf as extreme;  am I supposed to score this higher because I recognize the face?  Does that make it a better photograph?', '2005-04-14 09:02:07.000000', NULL, 1),
(1291174, 165114, 11895, '<td valign="top">the sel desat is appropriate to emphasize and isolate the action but it''s hard for me to think of playing frisbee on a beach as extreme</td>', 'the sel desat is appropriate to emphasize and isolate the action but it''s hard for me to think of playing frisbee on a beach as extreme', '2005-04-14 09:18:40.000000', NULL, 1),
(1291193, 164797, 23458, '<td valign="top">Well it might be cliched, done before, whatever, but you just won yourself a ribbon. Extremely well executed. Sure it would have been stronger without the little dint in the front of the can, and if you had figured out a way to actually pierce the can with a projectile or sudden burst rather than the sneaky means you''ve adopted here - not 100% sure exactly what you''ve done but I know there''s SOMETHING going on to the left of the frame, but still, I like this a lot. <br/> <br/>I''ll stop rambling and get to the point. <br/> <br/>10.</td>', 'Well it might be cliched, done before, whatever, but you just won yourself a ribbon. Extremely well executed. Sure it would have been stronger without the little dint in the front of the can, and if you had figured out a way to actually pierce the can with a projectile or sudden burst rather than the sneaky means you''ve adopted here - not 100% sure exactly what you''ve done but I know there''s SOMETHING going on to the left of the frame, but still, I like this a lot.  I''ll stop rambling and get to the point.  10.', '2005-04-14 09:32:14.000000', NULL, 1),
(1291215, 165115, 35122, '<td valign="top">very nice action shot....I love how the bike and rider is the only color in the pic....very nice!!!</td>', 'very nice action shot....I love how the bike and rider is the only color in the pic....very nice!!!', '2005-04-14 09:58:48.000000', NULL, 1),
(1291218, 163344, 35122, '<td valign="top">cool shot....</td>', 'cool shot....', '2005-04-14 10:02:21.000000', NULL, 1),
(1291311, 164935, 29797, '<td valign="top">This is brilliant! Incredible capture. I hope people have a sense of humor and give a great score, which it deserves.</td>', 'This is brilliant! Incredible capture. I hope people have a sense of humor and give a great score, which it deserves.', '2005-04-14 10:44:10.000000', NULL, 1),
(1291325, 163858, 26464, '<td valign="top">i like the humour to this one. good for you!</td>', 'i like the humour to this one. good for you!', '2005-04-14 10:47:52.000000', NULL, 1),
(1291376, 164238, 29797, '<td valign="top">WOW!!! Nice capture! I can feel the excitement you must''ve had looking through the viewfinder as you captured this. I could be wrong, but maybe a bit oversharpened. But that could be from having so much detail and compressing it down to only 150kb. Great shot!</td>', 'WOW!!! Nice capture! I can feel the excitement you must''ve had looking through the viewfinder as you captured this. I could be wrong, but maybe a bit oversharpened. But that could be from having so much detail and compressing it down to only 150kb. Great shot!', '2005-04-14 11:00:22.000000', NULL, 1),
(1291598, 165125, 11895, '<td valign="top">oversharpenned</td>', 'oversharpenned', '2005-04-14 12:08:43.000000', NULL, 1),
(1291710, 164238, 26679, '<td valign="top">This is a great capture<br/>I would normally mark down a picture when the back of the animal is towards us, but in this case this adds to the composition.<br/> <br/></td>', 'This is a great captureI would normally mark down a picture when the back of the animal is towards us, but in this case this adds to the composition. ', '2005-04-14 12:55:04.000000', NULL, 1),
