(5125502, 165099, 98141, '<td valign="top">I really enjoy this pic, I can''t believe the score it got. I love the colors in it and the fierceness of it - which is made even better by knowing that rather than a ferocious moment it is simply a yawn. Well done.</td>', 'I really enjoy this pic, I can''t believe the score it got. I love the colors in it and the fierceness of it - which is made even better by knowing that rather than a ferocious moment it is simply a yawn. Well done.', '2008-12-11 16:38:54.000000', NULL, 0),
(5660436, 164835, 50578, '<td valign="top">This is a nice action shot, We had tickets to Rugby for tonight but the weather was bad so we didn''t go. Lucky the tickets were free. If it had been the All Blacks playing we might have dealt with the weather.</td>', 'This is a nice action shot, We had tickets to Rugby for tonight but the weather was bad so we didn''t go. Lucky the tickets were free. If it had been the All Blacks playing we might have dealt with the weather.', '2009-09-24 07:38:11.000000', NULL, 0),
